import json
CSS=""":root{--bg:#F6F4EF;--card:#fff;--ink:#1C2B30;--mute:#5B6B70;--teal:#0E3F4A;--gold:#C8862A;--ok:#2E7D4F;--bad:#A23B2A;--line:#DCD8CE}
@media (prefers-color-scheme:dark){:root{--bg:#10191C;--card:#18252A;--ink:#E8EEEC;--mute:#9DB0B3;--teal:#7FC3CF;--gold:#E2B868;--ok:#6CC08F;--bad:#E07A68;--line:#2A3A40}}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.5 system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif}
main{max-width:640px;margin:0 auto;padding:20px 16px 40px}h1{font:700 26px Georgia,serif;color:var(--teal);margin:0 0 4px}.sub{color:var(--mute);margin:0 0 16px}
.bar{display:flex;justify-content:space-between;font-size:14px;color:var(--mute);margin-bottom:8px}.prog{height:6px;background:var(--line);border-radius:3px;overflow:hidden;margin-bottom:16px}.prog i{display:block;height:100%;background:var(--gold);transition:width .3s}
.card{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:18px}.case{font:600 13px system-ui;letter-spacing:1px;text-transform:uppercase;color:var(--gold)}
.q{margin:6px 0 14px;font-size:17px}.ar{direction:rtl;color:var(--mute);font-size:15px;margin:-6px 0 14px}
.opts{display:grid;gap:10px}button{font:inherit;cursor:pointer;border-radius:10px;border:1px solid var(--line);background:var(--bg);color:var(--ink);padding:12px 14px;text-align:start;font-weight:600}
button:disabled{cursor:default;opacity:1}button.ok{background:var(--ok);color:#fff;border-color:var(--ok)}button.bad{background:var(--bad);color:#fff;border-color:var(--bad)}button.used{opacity:.35}
.fb{margin-top:14px;padding:12px;border-radius:10px;display:none}.fb.ok{display:block;background:color-mix(in srgb,var(--ok) 14%,transparent)}.fb.bad{display:block;background:color-mix(in srgb,var(--bad) 14%,transparent)}
.next{margin-top:14px;width:100%;background:var(--teal);color:var(--bg);border:0;display:none;text-align:center}.end{text-align:center}.big{font:700 54px Georgia,serif;color:var(--teal)}
ol.seq{margin:0 0 12px;padding-inline-start:22px}ol.seq li{margin:4px 0}ol.seq li.bad{color:var(--bad)}ol.seq li.ok{color:var(--ok)}
.ref{margin-top:18px;font-size:14px;color:var(--mute)}.ref b{color:var(--ink)}"""
JS=r"""
const $=(id)=>document.getElementById(id);let i=0,score=0,max=0,t0=Date.now(),tm;
const sh=(a)=>{a=a.slice();for(let k=a.length-1;k>0;k--){const j=Math.floor(Math.random()*(k+1));[a[k],a[j]]=[a[j],a[k]]}return a};
function tick(){const s=Math.floor((Date.now()-t0)/1000);$('time').textContent='⏱ '+Math.floor(s/60)+':'+String(s%60).padStart(2,'0')}
function head(){$('count').textContent='Round '+(i+1)+' of '+G.length+' · score '+score;$('pg').style.width=(i/G.length*100)+'%'}
function nextBtn(){$('nx').style.display='block';$('nx').onclick=()=>{i++;i<G.length?show():end()}}
function show(){const c=G[i];head();let h='<div class="case">Round '+(i+1)+(c.t?' · '+c.t:'')+'</div><p class="q">'+c.q+'</p>'+(c.ar?'<p class="ar">'+c.ar+'</p>':'');
if(c.order){h+='<ol class="seq" id="seq"></ol><div class="opts" id="op">'+sh(c.order.map((s,k)=>[s,k])).map(([s,k])=>'<button data-k="'+k+'">'+s+'</button>').join('')+'</div>'}
else h+='<div class="opts">'+(c.keep?c.o:sh(c.o)).map(o=>'<button data-o="'+o.replace(/"/g,'&quot;')+'">'+o+'</button>').join('')+'</div>';
h+='<div class="fb" id="fb"></div><button class="next" id="nx">'+(i<G.length-1?'Next →':'See my score')+'</button>';$('box').innerHTML=h;
if(c.order){max+=c.order.length;let picked=[];document.querySelectorAll('[data-k]').forEach(b=>b.onclick=()=>{if(b.disabled)return;b.disabled=true;b.classList.add('used');picked.push(+b.dataset.k);
const li=document.createElement('li');li.textContent=c.order[+b.dataset.k];$('seq').appendChild(li);
if(picked.length===c.order.length){let ok=0;[...$('seq').children].forEach((x,n)=>{const g=picked[n]===n;if(g)ok++;x.className=g?'ok':'bad'});score+=ok;head();
const f=$('fb');f.className='fb '+(ok===c.order.length?'ok':'bad');f.innerHTML='<b>'+ok+' of '+c.order.length+' in the right place.</b> Correct order:<ol class="seq">'+c.order.map(s=>'<li>'+s+'</li>').join('')+'</ol>'+(c.why||'');nextBtn()}})}
else{max+=1;document.querySelectorAll('[data-o]').forEach(b=>b.onclick=()=>{const ok=b.dataset.o===c.a;if(ok)score++;document.querySelectorAll('[data-o]').forEach(x=>{x.disabled=true;if(x.dataset.o===c.a)x.classList.add('ok')});if(!ok)b.classList.add('bad');
const f=$('fb');f.className='fb '+(ok?'ok':'bad');f.innerHTML=(ok?'<b>Correct ✓</b> ':'<b>Not quite: '+c.a+'.</b> ')+c.why;head();nextBtn()})}}
function end(){clearInterval(tm);tick();$('pg').style.width='100%';$('ref').hidden=false;const s=Math.floor((Date.now()-t0)/1000),p=score/max;
$('box').innerHTML='<div class="end"><div class="case">Your result</div><div class="big">'+score+' / '+max+'</div><p>'+(p===1?'Perfect! 🏆':p>=.7?'Well done 👏':'Review the summary below and try again 💪')+'</p><p class="sub">Time: '+Math.floor(s/60)+':'+String(s%60).padStart(2,'0')+'</p><button class="next" style="display:block" id="again">Play again</button></div>';
$('again').onclick=()=>{$('ref').hidden=true;i=0;score=0;max=0;t0=Date.now();tm=setInterval(tick,1000);show()}}
tm=setInterval(tick,1000);show();"""
def page(fn,title,sub,ref,G):
    open(fn,'w').write(f"""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{title}</title><style>{CSS}</style></head><body><main>
<h1>{title}</h1><p class="sub">{sub}</p><div class="bar"><span id="count"></span><span id="time">⏱ 0:00</span></div><div class="prog"><i id="pg" style="width:0"></i></div>
<div class="card" id="box"></div><div class="ref" id="ref" hidden><b>Summary:</b> {ref}</div></main><script>const G={json.dumps(G,ensure_ascii=False)};{JS}</script></body></html>""")
D='/home/claude/conservative-dentistry-year-3-digital-logbook/public/guides/'
page(D+'Game_Prep_Steps.html','Prep Steps in Order','2 rounds · tap the steps in the right order · <span dir="rtl">رتّب خطوات التحضير</span>',
 'Assess → protect → enter at the right spot → extend at the right depth → remove remaining caries → refine the walls and margins → check with the probe and clean.',
 [{'t':'Class I for composite','q':'Tap the 7 steps of a Class I composite preparation in order.','ar':'اضغط على خطوات تحضير Class I للكومبوزيت بالترتيب.',
   'order':['Examine the tooth and mark the occlusal contacts','Choose the bur (small pear-shaped #330 or round diamond)','Enter at the deepest pit, bur parallel to the long axis','Extend along the defective fissures only, about 1.5–2 mm deep','Remove the remaining carious dentin (slow speed, round bur)','Smooth the walls and round the internal angles','Check the depth with the periodontal probe, then wash and dry'],
   'why':' Composite is bonded, so the outline follows the defect only: no extension for prevention and no retention grooves.'},
  {'t':'Compound Class II for composite','q':'Tap the 7 steps of a compound (occluso-proximal) Class II composite preparation in order.','ar':'رتّب خطوات تحضير Class II مركّب للكومبوزيت.',
   'order':['Examine the tooth, contacts and the marginal ridge','Protect the adjacent tooth with a wedge or metal matrix band','Prepare the occlusal part: enter at the pit next to the affected marginal ridge','Cut the proximal ditch, keeping a thin wall of enamel against the neighbour','Break the remaining enamel wall away and extend the box only as far as the caries','Remove the remaining caries and any unsupported, friable enamel','Round the internal angles, check the gingival floor with the probe and clean'],
   'why':' Protecting the adjacent tooth comes before any proximal cutting.'}])
page(D+'Game_Bur_Match.html','Match the Instrument','6 rounds · choose the instrument for each job · <span dir="rtl">اختار الأداة المناسبة</span>',
 'Pear #330/#245: outline of conservative preparations · large round bur at slow speed: carious dentin · inverted cone #33½: undercuts for amalgam · flame diamond: enamel bevels · 12-fluted carbide: finishing composite · gingival margin trimmer: gingival margin of the box.',
 [{'q':'Outlining a conservative Class I preparation for composite.','ar':'عمل الـ outline لتحضير Class I محافظ للكومبوزيت.','o':['Pear-shaped carbide #330','Inverted cone #33½','Flame diamond','Large round bur, slow speed'],'a':'Pear-shaped carbide #330','why':'The small pear bur gives a narrow outline with rounded internal angles.'},
  {'q':'Removing soft carious dentin from the pulpal floor.','ar':'إزالة العاج المسوس الطري من أرضية الحفرة.','o':['Large round bur, slow speed','Pear-shaped carbide #330, high speed','Flame diamond','12-fluted finishing carbide'],'a':'Large round bur, slow speed','why':'Slow speed with a large round bur gives control and tactile feedback near the pulp.'},
  {'q':'Placing undercuts (retention) in an amalgam preparation.','ar':'عمل undercuts للتثبيت في تحضير الأملجم.','o':['Inverted cone #33½','Pear-shaped carbide #330','Flame diamond','Large round bur, slow speed'],'a':'Inverted cone #33½','why':'Amalgam does not bond, so it relies on mechanical retention such as undercuts.'},
  {'q':'Bevelling the enamel margin of a Class IV composite preparation.','ar':'عمل bevel لحافة المينا في تحضير Class IV للكومبوزيت.','o':['Flame diamond','Inverted cone #33½','Large round bur, slow speed','Gingival margin trimmer'],'a':'Flame diamond','why':'A bevel on anterior enamel increases the bonding area and blends the restoration.'},
  {'q':'Finishing and contouring a set composite restoration.','ar':'تشطيب وتشكيل حشو الكومبوزيت بعد التصلب.','o':['12-fluted finishing carbide','Inverted cone #33½','Large round bur, slow speed','Pear-shaped carbide #330'],'a':'12-fluted finishing carbide','why':'Multi-fluted carbides (or fine diamonds and discs) remove little material and leave a smooth surface.'},
  {'q':'Planing and bevelling the gingival margin of a Class II box.','ar':'تنعيم وعمل bevel للحافة اللثوية في الـ box.','o':['Gingival margin trimmer','Flame diamond','Pear-shaped carbide #330','Inverted cone #33½'],'a':'Gingival margin trimmer','why':'This hand instrument removes unsupported enamel rods at the gingival margin.'}])
page(D+'Game_Spot_The_Error.html','Spot the Preparation Error','6 cases · what is wrong with this preparation? · <span dir="rtl">اكتشف الخطأ في التحضير</span>',
 'Composite preparations: as conservative as possible, about 1.5–2 mm deep for a small occlusal lesion, rounded internal angles, no unsupported enamel, adjacent tooth protected, no occlusal bevel on posterior teeth.',
 [{'q':'Class I composite on tooth 36. The probe reads 3.5 mm on the pulpal floor for a small occlusal lesion.','ar':'Class I كومبوزيت على سن ٣٦، والبروب بيقرا ٣٫٥ مم لتسوس إطباقي صغير.','o':['Too deep','Too shallow','Outline too narrow','Nothing is wrong'],'a':'Too deep','why':'About 1.5–2 mm (just into dentin) is enough for a small lesion; extra depth weakens the tooth and approaches the pulp.'},
  {'q':'Class I composite. The walls are smooth but the internal line angles are sharp.','ar':'Class I كومبوزيت، الجدران ناعمة لكن الزوايا الداخلية حادة.','o':['Internal angles should be rounded','Walls should diverge more','A bevel is missing','Nothing is wrong'],'a':'Internal angles should be rounded','why':'Rounded angles reduce stress concentration and let the composite adapt without voids.'},
  {'q':'Compound Class II on tooth 46. After the box, the mesial surface of tooth 45 is scratched.','ar':'Class II على سن ٤٦، وبعد الـ box السطح الـ mesial لسن ٤٥ متجرّح.','o':['The adjacent tooth was not protected','The box is too narrow','The gingival floor is too deep','Nothing is wrong'],'a':'The adjacent tooth was not protected','why':'Place a wedge or metal matrix and keep a thin enamel wall while cutting the proximal ditch.'},
  {'q':'Class II for composite. Thin enamel without dentin support is left on the buccal wall of the box.','ar':'Class II كومبوزيت، فيه مينا رفيعة من غير عاج تحتها على الجدار الـ buccal للـ box.','o':['Unsupported enamel must be removed','The box must be deepened','A retention groove is needed','Nothing is wrong'],'a':'Unsupported enamel must be removed','why':'Friable unsupported enamel fractures under load and leaves a marginal gap.'},
  {'q':'Class II for composite with an isthmus about half the intercuspal distance; the caries was small.','ar':'Class II كومبوزيت والـ isthmus حوالي نص المسافة بين الحدبات، والتسوس كان صغير.','o':['Isthmus too wide','Isthmus too narrow','Box too shallow','Nothing is wrong'],'a':'Isthmus too wide','why':'Composite allows a narrow, conservative isthmus; a wide one weakens the cusps.'},
  {'q':'Class I composite on a molar with a wide bevel placed all around the occlusal cavosurface margin.','ar':'Class I كومبوزيت على ضرس، مع bevel عريض حوالين الحافة الإطباقية كلها.','o':['Occlusal bevel is not indicated on posterior teeth','The bevel should be wider','A bevel is also needed on the pulpal floor','Nothing is wrong'],'a':'Occlusal bevel is not indicated on posterior teeth','why':'A thin composite edge at the occlusal margin wears and chips under occlusal contacts.'}])
page(D+'Game_Composite_vs_Amalgam.html','Composite or Amalgam?','8 rounds · which preparation design does each feature belong to? · <span dir="rtl">كومبوزيت ولا أملجم؟</span>',
 'Amalgam: mechanical retention, 90° butt-joint margins, minimum thickness for strength. Composite: retention by bonding, conservative outline, bevels on anterior enamel. Both: remove caries, rounded internal angles, no unsupported enamel.',
 [{'q':'Retention comes mainly from bonding to enamel and dentin.','o':['Composite','Amalgam','Both'],'keep':1,'a':'Composite','why':'Adhesive restorations do not need undercuts.'},
  {'q':'Needs undercuts or convergent walls to stay in place.','o':['Composite','Amalgam','Both'],'keep':1,'a':'Amalgam','why':'Amalgam does not bond, so retention is mechanical.'},
  {'q':'Cavosurface margin at about 90° (butt joint).','o':['Composite','Amalgam','Both'],'keep':1,'a':'Amalgam','why':'Thin edges of amalgam are brittle and fracture.'},
  {'q':'A minimum thickness (about 1.5–2 mm) is needed for the material’s strength.','o':['Composite','Amalgam','Both'],'keep':1,'a':'Amalgam','why':'Amalgam needs bulk to resist fracture; composite depth simply follows the caries.'},
  {'q':'The outline is limited to the caries or defect only.','o':['Composite','Amalgam','Both'],'keep':1,'a':'Composite','why':'Bonding allows the most conservative outline.'},
  {'q':'Enamel margins of anterior preparations (Class III and IV) may be bevelled.','o':['Composite','Amalgam','Both'],'keep':1,'a':'Composite','why':'A bevel increases the etched enamel area and improves aesthetics.'},
  {'q':'Internal line angles should be rounded.','o':['Composite','Amalgam','Both'],'keep':1,'a':'Both','why':'Rounded angles reduce stress in the tooth for both materials.'},
  {'q':'All infected dentin and unsupported enamel are removed.','o':['Composite','Amalgam','Both'],'keep':1,'a':'Both','why':'This rule applies to every preparation.'}])
